------ Notes  
Insert into celink.tblLoanNotes 
	(INTSUBSERVICERLOANNUMBER, CHRLOANNOTES, DTMNOTEDATE, CHRUSERID, BLNPRIORITY, NOTESTEP)

with MyVal (SEQNUM, HDTNUM, REQUESTER, LOAN, Baad, Good, UpdtCol) as
(VALUES
(1, 0175255, 'Jordann Greene', 3338348, 0.06045, 0.06, 'Expected Average Rate'),
(2, 0175255, 'Jordann Greene', 3338349, 0.0647, 0.065, 'Expected Average Rate')
)	
Select 
--	SeqNum ,
	Loan	
	,
   'Per HDT ' || UY.HDTNum || ' Expected Average Interest Rate updated from ' || trim(VARCHAR_FORMAT(UY.Baad, '0.000000')) || ' to ' || trim(VARCHAR_FORMAT(UY.Good, '0.000000')) || '.'  
	,
	CURRENT_TIMESTAMP,		--CHAR(Current Date, USA) || ' ' || char(Current Time, USA),
	'tkato', 
	0,
	0
from MyVal UY  
Order by SeqNum 
; 

-- LOAN    2                                                                                3                          4     5 6
