-- 3338348 Per HDT 175255 Expected Average Interest Rate updated from 0.060450 to 0.060000. 2024-10-18 12:22:56.878169 tkato 0 0
-- 3338349 Per HDT 175255 Expected Average Interest Rate updated from 0.064700 to 0.065000. 2024-10-18 12:22:56.878169 tkato 0 0

	------------------
	-- Notes validation
	with MyVal (SEQNUM, HDTNUM, REQUESTER, LOAN, Baad, Good, UpdtCol) as
	(VALUES

(1, 0175255, 'Jordann Greene', 3338348, 0.06045, 0.06, 'Expected Average Rate'),
(2, 0175255, 'Jordann Greene', 3338349, 0.0647, 0.065, 'Expected Average Rate')
	
	)	
	select 
	--	count(*) as "MyCount"
		UY.SeqNum,
		a.DTMNOTEDATE,	a.IDSLOANNOTES,	a.INTSUBSERVICERLOANNUMBER,	a.CHRLOANNOTES, a.CHRUSERID, a.BLNPRIORITY, NOTESTEP --,*
	from MyVal UY  
	inner join	celink.tblloannotes a  
	on  UY.loan = a.INTSUBSERVICERLOANNUMBER 
	and a.CHRLOANNOTES like 'Per%HDT%' || HDTNum ||'%'
	
	order by UY.SeqNum --a.IDSLOANNOTES desc 
	with ur;

